 166:   public void testPrint() {
 167:     assertPrint("10 + a + b", "10+a+b");
 168:     assertPrint("10 + (30*50)", "10+30*50");
 169:     assertPrint("with(x) { x + 3; }", "with(x)x+3");
 170:     assertPrint("\"aa'a\"", "\"aa'a\"");
 171:     assertPrint("\"aa\\\"a\"", "'aa\"a'");
 172:     assertPrint("function foo()\n{return 10;}", "function foo(){return 10}");
 173:     assertPrint("a instanceof b", "a instanceof b");
 174:     assertPrint("typeof(a)", "typeof a");
 175:     assertPrint(
 176:         "var foo = x ? { a : 1 } : {a: 3, b:4, \"default\": 5, \"foo-bar\": 6}",
 177:         "var foo=x?{a:1}:{a:3,b:4,\"default\":5,\"foo-bar\":6}");
 178: 
 179:     // Safari: needs ';' at the end of a throw statement
 180:     assertPrint("function foo(){throw 'error';}",
 181:         "function foo(){throw\"error\";}");
 182:     // Safari 3 needs a "{" around a single function
 183:     assertPrint("if (true) function foo(){return}",
 184:         "if(true){function foo(){return}}");
 185: 
 186:     assertPrint("var x = 10; { var y = 20; }", "var x=10;var y=20");
 187: 
 188:     assertPrint("while (x-- > 0);", "while(x-- >0);");
 189:     assertPrint("x-- >> 1", "x-- >>1");
 190: 
 191:     assertPrint("(function () {})(); ",
 192:         "(function(){})()");
 193: 
 194:     // Associativity
 195:     assertPrint("var a,b,c,d;a || (b&& c) && (a || d)",
 196:         "var a,b,c,d;a||b&&c&&(a||d)");
 197:     assertPrint("var a,b,c; a || (b || c); a * (b * c); a | (b | c)",
 198:         "var a,b,c;a||(b||c);a*(b*c);a|(b|c)");
 199:     assertPrint("var a,b,c; a / b / c;a / (b / c); a - (b - c);",
 200:         "var a,b,c;a/b/c;a/(b/c);a-(b-c)");
 201: 
 202:     // Nested assignments
 203:     assertPrint("var a,b; a = b = 3;",
 204:         "var a,b;a=b=3");
 205:     assertPrint("var a,b,c,d; a = (b = c = (d = 3));",
 206:         "var a,b,c,d;a=b=c=d=3");
 207:     assertPrint("var a,b,c; a += (b = c += 3);",
 208:         "var a,b,c;a+=b=c+=3");
 209:     assertPrint("var a,b,c; a *= (b -= c);",
 210:         "var a,b,c;a*=b-=c");
 211: 
 212:     // Precedence
 213:     assertPrint("a ? delete b[0] : 3", "a?delete b[0]:3");
 214:     assertPrint("(delete a[0])/10", "delete a[0]/10");
 215: 
 216:     // optional '()' for new
 217: 
 218:     // simple new
 219:     assertPrint("new A", "new A");
 220:     assertPrint("new A()", "new A");
 221:     assertPrint("new A('x')", "new A(\"x\")");
 222: 
 223:     // calling instance method directly after new
 224:     assertPrint("new A().a()", "(new A).a()");
 225:     assertPrint("(new A).a()", "(new A).a()");
 226: 
 227:     // this case should be fixed
 228:     assertPrint("new A('y').a()", "(new A(\"y\")).a()");
 229: 
 230:     // internal class
 231:     assertPrint("new A.B", "new A.B");
 232:     assertPrint("new A.B()", "new A.B");
 233:     assertPrint("new A.B('z')", "new A.B(\"z\")");
 234: 
 235:     // calling instance method directly after new internal class
 236:     assertPrint("(new A.B).a()", "(new A.B).a()");
 237:     assertPrint("new A.B().a()", "(new A.B).a()");
 238:     // this case should be fixed
