 240: 
 241:     // Operators: make sure we don't convert binary + and unary + into ++
 242:     assertPrint("x + +y", "x+ +y");
 243:     assertPrint("x - (-y)", "x- -y");
 244:     assertPrint("x++ +y", "x++ +y");
 245:     assertPrint("x-- -y", "x-- -y");
 246:     assertPrint("x++ -y", "x++-y");
 247: 
 248:     // Label
 249:     assertPrint("foo:for(;;){break foo;}", "foo:for(;;)break foo");
 250:     assertPrint("foo:while(1){continue foo;}", "foo:while(1)continue foo");
 251: 
 252:     // Object literals.
 253:     assertPrint("({})", "({})");
 254:     assertPrint("var x = {};", "var x={}");
 255:     assertPrint("({}).x", "({}).x");
 256:     assertPrint("({})['x']", "({})[\"x\"]");
 257:     assertPrint("({}) instanceof Object", "({})instanceof Object");
 258:     assertPrint("({}) || 1", "({})||1");
