 263:     assertPrint("typeof ({})", "typeof{}");
 264:     assertPrint("f({})", "f({})");
 265: 
 266:     // Anonymous function expressions.
 267:     assertPrint("(function(){})", "(function(){})");
 268:     assertPrint("(function(){})()", "(function(){})()");
 269:     assertPrint("(function(){})instanceof Object",
 270:         "(function(){})instanceof Object");
 271:     assertPrint("(function(){}).bind().call()",
