 273:     assertPrint("var x = function() { };", "var x=function(){}");
 274:     assertPrint("var x = function() { }();", "var x=function(){}()");
 275:     assertPrint("(function() {}), 2", "(function(){}),2");
 276: 
 277:     // Name functions expression.
 278:     assertPrint("(function f(){})", "(function f(){})");
 279: 
 280:     // Function declaration.
 281:     assertPrint("function f(){}", "function f(){}");
 282: 
 283:     // Make sure we don't treat non-Latin character escapes as raw strings.
 284:     assertPrint("({ 'a': 4, '\\u0100': 4 })", "({\"a\":4,\"\\u0100\":4})");
 285:     assertPrint("({ a: 4, '\\u0100': 4 })", "({a:4,\"\\u0100\":4})");
 286: 
 287:     // Test if statement and for statements with single statements in body.
 288:     assertPrint("if (true) { alert();}", "if(true)alert()");
 289:     assertPrint("if (false) {} else {alert(\"a\");}",
 290:         "if(false);else alert(\"a\")");
 291:     assertPrint("for(;;) { alert();};", "for(;;)alert()");
 292: 
 293:     assertPrint("do { alert(); } while(true);",
 294:         "do alert();while(true)");
 295:     assertPrint("myLabel: { alert();}",
 296:         "myLabel:alert()");
 297:     assertPrint("myLabel: for(;;) continue myLabel;",
 298:         "myLabel:for(;;)continue myLabel");
 299: 
 300:     // Test nested var statement
 301:     assertPrint("if (true) var x; x = 4;", "if(true)var x;x=4");
 302: 
 303:     // Non-latin identifier. Make sure we keep them escaped.
 304:     assertPrint("\\u00fb", "\\u00fb");
 305:     assertPrint("\\u00fa=1", "\\u00fa=1");
 306:     assertPrint("function \\u00f9(){}", "function \\u00f9(){}");
 307:     assertPrint("x.\\u00f8", "x.\\u00f8");
 308:     assertPrint("x.\\u00f8", "x.\\u00f8");
 309:     assertPrint("abc\\u4e00\\u4e01jkl", "abc\\u4e00\\u4e01jkl");
 310: 
 311:     // Test the right-associative unary operators for spurious parens
 312:     assertPrint("! ! true", "!!true");
 313:     assertPrint("!(!(true))", "!!true");
 314:     assertPrint("typeof(void(0))", "typeof void 0");
 315:     assertPrint("typeof(void(!0))", "typeof void!0");
 316:     assertPrint("+ - + + - + 3", "+-+ +-+3"); // chained unary plus/minus
 317:     assertPrint("+(--x)", "+--x");
 318:     assertPrint("-(++x)", "-++x");
 319: 
 320:     // needs a space to prevent an ambiguous parse
 321:     assertPrint("-(--x)", "- --x");
 322:     assertPrint("!(~~5)", "!~~5");
 323:     assertPrint("~(a/b)", "~(a/b)");
 324: 
 325:     // Preserve parens to overcome greedy binding of NEW
 326:     assertPrint("new (foo.bar()).factory(baz)", "new (foo.bar().factory)(baz)");
 327:     assertPrint("new (bar()).factory(baz)", "new (bar().factory)(baz)");
 328:     assertPrint("new (new foobar(x)).factory(baz)",
 329:         "new (new foobar(x)).factory(baz)");
 330: 
 331:     // Make sure that HOOK is right associative
 332:     assertPrint("a ? b : (c ? d : e)", "a?b:c?d:e");
 333:     assertPrint("a ? (b ? c : d) : e", "a?b?c:d:e");
 334:     assertPrint("(a ? b : c) ? d : e", "(a?b:c)?d:e");
 335: 
 336:     // Test nested ifs
 337:     assertPrint("if (x) if (y); else;", "if(x)if(y);else;");
 338: 
 339:     // Test comma.
 340:     assertPrint("a,b,c", "a,b,c");
 341:     assertPrint("(a,b),c", "a,b,c");
 342:     assertPrint("a,(b,c)", "a,b,c");
 343:     assertPrint("x=a,b,c", "x=a,b,c");
 344:     assertPrint("x=(a,b),c", "x=(a,b),c");
 345:     assertPrint("x=a,(b,c)", "x=a,b,c");
 346:     assertPrint("x=a,y=b,z=c", "x=a,y=b,z=c");
 347:     assertPrint("x=(a,y=b,z=c)", "x=(a,y=b,z=c)");
 348:     assertPrint("x=[a,b,c,d]", "x=[a,b,c,d]");
 349:     assertPrint("x=[(a,b,c),d]", "x=[(a,b,c),d]");
