 351:     assertPrint("x=[a,(b,c,d)]", "x=[a,(b,c,d)]");
 352:     assertPrint("var x=(a,b)", "var x=(a,b)");
 353:     assertPrint("var x=a,b,c", "var x=a,b,c");
 354:     assertPrint("var x=(a,b),c", "var x=(a,b),c");
 355:     assertPrint("var x=a,b=(c,d)", "var x=a,b=(c,d)");
