 359:     assertPrint("f(a+b,(c,d,(e,f,g)))", "f(a+b,(c,d,e,f,g))");
 360:     assertPrint("({}) , 1 , 2", "({}),1,2");
 361:     assertPrint("({}) , {} , {}", "({}),{},{}");
