 441:   public void testPrintInOperatorInForLoop() {
 442:     // Check for in expression in for's init expression.
 443:     // Check alone, with + (higher precedence), with ?: (lower precedence),
 444:     // and with conditional.
 445:     assertPrint("var a={}; for (var i = (\"length\" in a); i;) {}",
 446:         "var a={};for(var i=(\"length\"in a);i;);");
 447:     assertPrint("var a={}; for (var i = (\"length\" in a) ? 0 : 1; i;) {}",
 448:         "var a={};for(var i=(\"length\"in a)?0:1;i;);");
 449:     assertPrint("var a={}; for (var i = (\"length\" in a) + 1; i;) {}",
 450:         "var a={};for(var i=(\"length\"in a)+1;i;);");
 451:     assertPrint("var a={};for (var i = (\"length\" in a|| \"size\" in a);;);",
 452:         "var a={};for(var i=(\"length\"in a)||(\"size\"in a);;);");
 453:     assertPrint("var a={};for (var i = (a || a) || (\"size\" in a);;);",
 454:         "var a={};for(var i=a||a||(\"size\"in a);;);");
 455: 
 456:     // Test works with unary operators and calls.
 457:     assertPrint("var a={}; for (var i = -(\"length\" in a); i;) {}",
 458:         "var a={};for(var i=-(\"length\"in a);i;);");
 459:     assertPrint("var a={};function b_(p){ return p;};" +
 460:         "for(var i=1,j=b_(\"length\" in a);;) {}",
 461:         "var a={};function b_(p){return p}" +
 462:             "for(var i=1,j=b_(\"length\"in a);;);");
 463: 
 464:     // Test we correctly handle an in operator in the test clause.
 465:     assertPrint("var a={}; for (;(\"length\" in a);) {}",
 466:         "var a={};for(;\"length\"in a;);");
 467: 
 468:     // Test we correctly handle an in operator inside a comma.
 469:     assertPrintSame("for(x,(y in z);;)foo()");
 470:     assertPrintSame("for(var x,w=(y in z);;)foo()");
 471: 
 472:     // And in operator inside a hook.
 473:     assertPrintSame("for(a=c?0:(0 in d);;)foo()");
 474:   }
