 601:   public void testPrettyPrinter() {
 602:     // Ensure that the pretty printer inserts line breaks at appropriate
 603:     // places.
 604:     assertPrettyPrint("(function(){})();","(function() {\n})();\n");
 605:     assertPrettyPrint("var a = (function() {});alert(a);",
 606:         "var a = function() {\n};\nalert(a);\n");
 607: 
 608:     // Check we correctly handle putting brackets around all if clauses so
 609:     // we can put breakpoints inside statements.
 610:     assertPrettyPrint("if (1) {}",
 611:         "if(1) {\n" +
 612:         "}\n");
 613:     assertPrettyPrint("if (1) {alert(\"\");}",
 614:         "if(1) {\n" +
 615:         "  alert(\"\")\n" +
 616:         "}\n");
 617:     assertPrettyPrint("if (1)alert(\"\");",
 618:         "if(1) {\n" +
 619:         "  alert(\"\")\n" +
 620:         "}\n");
 621:     assertPrettyPrint("if (1) {alert();alert();}",
 622:         "if(1) {\n" +
 623:         "  alert();\n" +
 624:         "  alert()\n" +
 625:         "}\n");
 626: 
 627:     // Don't add blocks if they weren't there already.
 628:     assertPrettyPrint("label: alert();",
 629:         "label:alert();\n");
 630: 
 631:     // But if statements and loops get blocks automagically.
 632:     assertPrettyPrint("if (1) alert();",
 633:         "if(1) {\n" +
 634:         "  alert()\n" +
 635:         "}\n");
 636:     assertPrettyPrint("for (;;) alert();",
 637:         "for(;;) {\n" +
 638:         "  alert()\n" +
 639:         "}\n");
 640: 
 641:     assertPrettyPrint("while (1) alert();",
 642:         "while(1) {\n" +
 643:         "  alert()\n" +
 644:         "}\n");
 645: 
 646:     // Do we put else clauses in blocks?
 647:     assertPrettyPrint("if (1) {} else {alert(a);}",
 648:         "if(1) {\n" +
 649:         "}else {\n  alert(a)\n}\n");
 650: 
 651:     // Do we add blocks to else clauses?
 652:     assertPrettyPrint("if (1) alert(a); else alert(b);",
 653:         "if(1) {\n" +
 654:         "  alert(a)\n" +
 655:         "}else {\n" +
 656:         "  alert(b)\n" +
 657:         "}\n");
 658: 
 659:     // Do we put for bodies in blocks?
 660:     assertPrettyPrint("for(;;) { alert();}",
 661:         "for(;;) {\n" +
 662:          "  alert()\n" +
 663:          "}\n");
 664:     assertPrettyPrint("for(;;) {}",
 665:         "for(;;) {\n" +
 666:         "}\n");
 667:     assertPrettyPrint("for(;;) { alert(); alert(); }",
 668:         "for(;;) {\n" +
 669:         "  alert();\n" +
 670:         "  alert()\n" +
 671:         "}\n");
 672: 
 673:     // How about do loops?
 674:     assertPrettyPrint("do { alert(); } while(true);",
 675:         "do {\n" +
 676:         "  alert()\n" +
 677:         "}while(true);\n");
 678: 
 679:     // label?
 680:     assertPrettyPrint("myLabel: { alert();}",
 681:         "myLabel: {\n" +
 682:         "  alert()\n" +
 683:         "}\n");
 684: 
 685:     // Don't move the label on a loop, because then break {label} and
 686:     // continue {label} won't work.
 687:     assertPrettyPrint("myLabel: for(;;) continue myLabel;",
 688:         "myLabel:for(;;) {\n" +
 689:         "  continue myLabel\n" +
 690:         "}\n");
 691: 
 692:     assertPrettyPrint("var a;", "var a;\n");
 693:   }
